SELECT * FROM purchase_main
WHERE employee_id = #{employeeId}
  AND purchase_time >= #{today}
  AND status = 'DRAFT'
LIMIT 1

SELECT pm.*, e.name AS employee_name
FROM purchase_main pm
LEFT JOIN employee e ON pm.employee_id = e.id
WHERE 1=1

    AND pm.employee_id = #{employeeId}


    AND pm.status = #{status}

ORDER BY pm.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM purchase_main
WHERE 1=1

    AND employee_id = #{employeeId}


    AND status = #{status}
